class Node:
    def __init__(self, val=None, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    def evaluate(self) -> int:
        if self.left is None:
            return self.val
        l, r = self.left.evaluate(), self.right.evaluate()
        if self.val == '+':
            return l + r
        if self.val == '-':
            return l - r
        if self.val == '*':
            return l * r
        return int(l / r)


class TreeBuilder:
    def buildTree(self, postfix: List[str]) -> 'Node':
        stack = []
        for tok in postfix:
            if tok.lstrip('-').isdigit():
                stack.append(Node(int(tok)))
            else:
                right = stack.pop()
                left = stack.pop()
                stack.append(Node(tok, left, right))
        return stack.pop()

