class Node {
public:
    Node(long long v) : value(v) {}
    Node(char op, Node* left, Node* right) : op(op), left(left), right(right) {}

    int evaluate() const {
        if (!left) return static_cast<int>(value);
        long long l = left->evaluate(), r = right->evaluate();
        switch (op) {
            case '+': return static_cast<int>(l + r);
            case '-': return static_cast<int>(l - r);
            case '*': return static_cast<int>(l * r);
            default:  return static_cast<int>(l / r);
        }
    }

private:
    char op = 0;
    long long value = 0;
    Node* left = nullptr;
    Node* right = nullptr;

    friend class TreeBuilder;
};

class TreeBuilder {
public:
    Node* buildTree(vector<string>& postfix) {
        vector<Node*> st;
        for (const string& tok : postfix) {
            if (tok.size() > 1 || isdigit(static_cast<unsigned char>(tok[0]))) {
                st.push_back(new Node(stoll(tok)));
            } else {
                Node* right = st.back(); st.pop_back();
                Node* left = st.back(); st.pop_back();
                st.push_back(new Node(tok[0], left, right));
            }
        }
        return st.back();
    }
};

