class Node {
    public char op;
    public long value;
    public Node left, right;

    public Node(long value) {
        this.value = value;
    }

    public Node(char op, Node left, Node right) {
        this.op = op;
        this.left = left;
        this.right = right;
    }

    public int evaluate() {
        if (left == null) return (int) value;
        long l = left.evaluate(), r = right.evaluate();
        switch (op) {
            case '+': return (int) (l + r);
            case '-': return (int) (l - r);
            case '*': return (int) (l * r);
            default:  return (int) (l / r);
        }
    }
}

class TreeBuilder {
    public Node buildTree(String[] postfix) {
        Deque<Node> stack = new ArrayDeque<>();
        for (String tok : postfix) {
            if (tok.length() > 1 || Character.isDigit(tok.charAt(0))) {
                stack.push(new Node(Long.parseLong(tok)));
            } else {
                Node right = stack.pop(), left = stack.pop();
                stack.push(new Node(tok.charAt(0), left, right));
            }
        }
        return stack.pop();
    }
}

