class Node {
public:
    virtual ~Node() {}
    virtual int evaluate() const = 0;
};

class NumNode : public Node {
public:
    NumNode(int v) : value(v) {}
    int evaluate() const override { return value; }
private:
    int value;
};

class BinaryOpNode : public Node {
public:
    BinaryOpNode(Node* l, Node* r) : left(l), right(r) {}
protected:
    Node* left;
    Node* right;
};

class AddNode : public BinaryOpNode {
public:
    AddNode(Node* l, Node* r) : BinaryOpNode(l, r) {}
    int evaluate() const override { return left->evaluate() + right->evaluate(); }
};

class SubNode : public BinaryOpNode {
public:
    SubNode(Node* l, Node* r) : BinaryOpNode(l, r) {}
    int evaluate() const override { return left->evaluate() - right->evaluate(); }
};

class MulNode : public BinaryOpNode {
public:
    MulNode(Node* l, Node* r) : BinaryOpNode(l, r) {}
    int evaluate() const override { return left->evaluate() * right->evaluate(); }
};

class DivNode : public BinaryOpNode {
public:
    DivNode(Node* l, Node* r) : BinaryOpNode(l, r) {}
    int evaluate() const override { return left->evaluate() / right->evaluate(); }
};

class TreeBuilder {
public:
    Node* buildTree(vector<string>& postfix) {
        vector<Node*> st;
        for (auto& tok : postfix) {
            bool isOp = tok == "+" || tok == "-" || tok == "*" || tok == "/";
            if (!isOp) {
                st.push_back(new NumNode(stoi(tok)));
                continue;
            }
            Node* right = st.back(); st.pop_back();
            Node* left = st.back(); st.pop_back();
            if (tok == "+") st.push_back(new AddNode(left, right));
            else if (tok == "-") st.push_back(new SubNode(left, right));
            else if (tok == "*") st.push_back(new MulNode(left, right));
            else st.push_back(new DivNode(left, right));
        }
        return st.back();
    }
};

