abstract class Node {
    public abstract int evaluate();
}

class NumNode extends Node {
    private final int value;

    NumNode(int value) {
        this.value = value;
    }

    @Override public int evaluate() {
        return value;
    }
}

abstract class BinaryOpNode extends Node {
    protected final Node left, right;

    BinaryOpNode(Node left, Node right) {
        this.left = left;
        this.right = right;
    }
}

class AddNode extends BinaryOpNode {
    AddNode(Node l, Node r) { super(l, r); }
    @Override public int evaluate() { return left.evaluate() + right.evaluate(); }
}

class SubNode extends BinaryOpNode {
    SubNode(Node l, Node r) { super(l, r); }
    @Override public int evaluate() { return left.evaluate() - right.evaluate(); }
}

class MulNode extends BinaryOpNode {
    MulNode(Node l, Node r) { super(l, r); }
    @Override public int evaluate() { return left.evaluate() * right.evaluate(); }
}

class DivNode extends BinaryOpNode {
    DivNode(Node l, Node r) { super(l, r); }
    @Override public int evaluate() { return left.evaluate() / right.evaluate(); }
}

class TreeBuilder {
    public Node buildTree(String[] postfix) {
        Deque<Node> stack = new ArrayDeque<>();
        for (String tok : postfix) {
            switch (tok) {
                case "+": {
                    Node r = stack.pop(), l = stack.pop();
                    stack.push(new AddNode(l, r));
                    break;
                }
                case "-": {
                    Node r = stack.pop(), l = stack.pop();
                    stack.push(new SubNode(l, r));
                    break;
                }
                case "*": {
                    Node r = stack.pop(), l = stack.pop();
                    stack.push(new MulNode(l, r));
                    break;
                }
                case "/": {
                    Node r = stack.pop(), l = stack.pop();
                    stack.push(new DivNode(l, r));
                    break;
                }
                default:
                    stack.push(new NumNode(Integer.parseInt(tok)));
            }
        }
        return stack.pop();
    }
}

